# Use robocopy trick to delete folders (copy empty folder over target)
$configPath = "D:\My Drive\Sync\Config\omniroute"

Write-Host "=== DELETE NON-ESSENTIAL FOLDERS (ROBOCOPY TRICK) ===" -ForegroundColor Cyan
Write-Host ""

# Create temp empty folder
$tempDir = "D:\Temp\empty_folder_$$"
if (Test-Path $tempDir) { Remove-Item $tempDir -Recurse -Force }
New-Item $tempDir -ItemType Directory | Out-Null

$folders = @("call_logs", "logs", "qoder-cli", "server", "supervisor")

foreach ($folder in $folders) {
    $folderPath = "$configPath\$folder"
    if (Test-Path $folderPath) {
